    "example_question_sqls": [
      {
        "id": "8b8dbae91e1b5919971a0299c6ca084c",
        "question": [
          "Recebedores com maior taxa de contestacao"
        ],
        "sql": [
          "SELECT autorizacoes.cnpj_recebedor, empresas_pj.razao_social, count(*) AS autorizacoes, round(avg(CASE WHEN autorizacoes.motivo_cancelamento LIKE 'Nao reconhece%' THEN 1 ELSE 0 END), 3) AS taxa_contestacao FROM workshop_nuclea_genie_catalog.pix.autorizacoes autorizacoes JOIN workshop_nuclea_genie_catalog.cadastro.empresas_pj empresas_pj ON empresas_pj.cnpj = autorizacoes.cnpj_recebedor GROUP BY ALL HAVING count(*) >= 50 ORDER BY taxa_contestacao DESC LIMIT 20"
        ]
      }
    ],
